//! Agent 集成投放框架（#83）。
//!
//! 三家（Claude / opencode / pi）采用**新增文件或目录**的方式：
//! - Claude：`~/.claude/skills/ageminal/` 插件目录；
//! - opencode：`~/.config/opencode/plugins/ageminal.ts`；
//! - pi：`~/.pi/agent/extensions/ageminal.ts`。
//!
//! Codex 需要改写用户 TOML，留给 #84；本模块把它显示为 `unsupported`。
//!
//! # 安全边界
//!
//! - 默认不写任何东西；只有用户在设置页确认 diff 后才 apply；
//! - 改既有文件前复制为 `<file>.ageminal-backup-<ts>`；
//! - 停用：Claude 删除自己的插件目录；opencode / pi 删除自己的文件，若存在用户原有
//!   （非 Ageminal 生成）的备份则恢复它；
//! - 内容带 `Generated by Ageminal` 标记，重复 apply 不产生 backup；注入物写 **shim 绝对路径**，
//!   不改 PATH。
//!
//! 注入物调用稳定路径 `%LOCALAPPDATA%\Ageminal\bin\ageminal-notify.exe`；应用启动时把
//! sidecar 复制到该位置（#31），因此应用更新后 hook 配置无需重写。

use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use ageminal_protocol::DaemonInfo;
use serde::Serialize;
use serde_json::json;
use specta::Type;

use crate::agents::AGENT_DEFAULTS;

/// 当前投放内容的版本；模板变化时递增，状态会显示「集成有更新」。
const INTEGRATION_VERSION: u32 = 1;

/// 生成物标记（用于禁用时区分用户文件与 Ageminal 文件）。
const GENERATED_MARKER: &str = "Generated by Ageminal";

/// 支持投放的四家；dsh 不在首批。
const SUPPORTED: [&str; 4] = ["claude", "opencode", "codex", "pi"];

/// 集成状态（设置页五态）。
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Type)]
#[serde(rename_all = "camelCase")]
pub enum IntegrationStatus {
    /// 未启用（没有任何 Ageminal 注入物）。
    NotEnabled,
    /// 全部当前版本。
    Enabled,
    /// 文件已存在但内容落后 / 路径变化。
    UpdateAvailable,
    /// 只有部分文件成功 / 存在。
    Partial,
    /// 该 agent 不走本框架（Codex 归 #84，dsh 不支持）。
    Unsupported,
}

/// diff / 状态里的文件动作。
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Type)]
#[serde(rename_all = "lowercase")]
pub enum IntegrationAction {
    /// 新建。
    Create,
    /// 覆盖更新。
    Update,
    /// 内容已一致。
    Unchanged,
}

/// 某个文件的状态投影。
#[derive(Debug, Clone, Serialize, Type)]
#[serde(rename_all = "camelCase")]
pub struct IntegrationFileView {
    /// 目标绝对路径。
    pub path: String,
    /// 当前动作。
    pub action: IntegrationAction,
}

/// 一个 agent 的集成状态。
#[derive(Debug, Clone, Serialize, Type)]
#[serde(rename_all = "camelCase")]
pub struct IntegrationView {
    /// agent id。
    pub agent_id: String,
    /// 显示名。
    pub name: String,
    /// 五态。
    pub status: IntegrationStatus,
    /// 已匹配的文件数。
    pub applied: u32,
    /// 期望文件总数。
    pub total: u32,
    /// shim 是否已复制到稳定路径。
    pub shim_ready: bool,
    /// 文件清单。
    pub files: Vec<IntegrationFileView>,
    /// 最近一次成功投递（Unix 毫秒）。
    pub last_delivery_ms: Option<f64>,
    /// notify-failures.log 中的失败行数。
    pub failure_count: u32,
    /// 不支持 / 失败原因。
    pub detail: Option<String>,
}

/// 预览中的一个文件。
#[derive(Debug, Clone, Serialize, Type)]
#[serde(rename_all = "camelCase")]
pub struct IntegrationPreviewFile {
    /// 目标路径。
    pub path: String,
    /// 动作。
    pub action: IntegrationAction,
    /// 将写入的 unified diff；无变化时为空。
    pub diff: String,
    /// 覆盖前会创建的备份路径。
    pub backup: Option<String>,
}

/// 应用前 diff 预览。
#[derive(Debug, Clone, Serialize, Type)]
#[serde(rename_all = "camelCase")]
pub struct IntegrationPreview {
    /// agent id。
    pub agent_id: String,
    /// 显示名。
    pub name: String,
    /// 是否支持。
    pub supported: bool,
    /// shim 是否已就绪。
    pub shim_ready: bool,
    /// 文件预览。
    pub files: Vec<IntegrationPreviewFile>,
}

/// apply / disable 的结果。
#[derive(Debug, Clone, Serialize, Type)]
#[serde(rename_all = "camelCase")]
pub struct IntegrationApplyResult {
    /// 最新状态。
    pub view: IntegrationView,
    /// 本次创建的备份路径。
    pub backups: Vec<String>,
    /// 部分失败的原因。
    pub errors: Vec<String>,
    /// 是否建议重启对应 agent。
    pub restart_required: bool,
}

/// 「测试投递」诊断。
#[derive(Debug, Clone, Serialize, Type)]
#[serde(rename_all = "camelCase")]
pub struct IntegrationTestResult {
    /// shim 是否成功完成握手 + 投递。
    pub delivered: bool,
    /// 诊断文本 / 失败原因。
    pub detail: String,
    /// 最新成功时间。
    pub last_delivery_ms: Option<f64>,
    /// 失败日志行数。
    pub failure_count: u32,
}

struct IntegrationContext {
    home: PathBuf,
    local: PathBuf,
    shim_source: PathBuf,
}

struct PlannedFile {
    path: PathBuf,
    content: String,
    old: Option<String>,
}

impl IntegrationContext {
    fn load() -> Result<Self, String> {
        let home = std::env::var_os("USERPROFILE")
            .or_else(|| std::env::var_os("HOME"))
            .map(PathBuf::from)
            .ok_or_else(|| "无法定位用户主目录（USERPROFILE / HOME）".to_owned())?;
        let local = std::env::var_os("LOCALAPPDATA")
            .map(PathBuf::from)
            .ok_or_else(|| "无法定位 LOCALAPPDATA".to_owned())?;
        let exe = std::env::current_exe().map_err(|error| error.to_string())?;
        let shim_source = find_shim(&exe)?;
        Ok(Self {
            home,
            local,
            shim_source,
        })
    }

    fn shim_target(&self) -> PathBuf {
        self.local
            .join("Ageminal")
            .join("bin")
            .join("ageminal-notify.exe")
    }

    fn config_dir(&self) -> PathBuf {
        self.local.join("Ageminal")
    }

    fn codex_path(&self) -> PathBuf {
        std::env::var_os("CODEX_HOME")
            .filter(|value| !value.is_empty())
            .map(PathBuf::from)
            .unwrap_or_else(|| self.home.join(".codex"))
            .join("config.toml")
    }

    fn ensure_shim(&self) -> Result<PathBuf, String> {
        if !self.shim_source.is_file() {
            return Err(format!(
                "找不到 ageminal-notify.exe：{}",
                self.shim_source.display()
            ));
        }
        let target = self.shim_target();
        if target.is_file() && fs::read(&target).ok() == fs::read(&self.shim_source).ok() {
            return Ok(target);
        }
        if let Some(parent) = target.parent() {
            fs::create_dir_all(parent).map_err(|error| error.to_string())?;
        }
        fs::copy(&self.shim_source, &target).map_err(|error| {
            format!(
                "复制 shim 到稳定路径失败（{} → {}）：{error}",
                self.shim_source.display(),
                target.display()
            )
        })?;
        Ok(target)
    }

    fn files(&self, agent: &str) -> Vec<(PathBuf, String)> {
        match agent {
            "claude" => {
                let root = self.home.join(".claude").join("skills").join("ageminal");
                vec![
                    (
                        root.join(".claude-plugin").join("plugin.json"),
                        claude_plugin_json(),
                    ),
                    (
                        root.join("hooks").join("hooks.json"),
                        claude_hooks_json(&self.shim_target()),
                    ),
                ]
            }
            "opencode" => vec![(
                self.home
                    .join(".config")
                    .join("opencode")
                    .join("plugins")
                    .join("ageminal.ts"),
                opencode_plugin(&self.shim_target()),
            )],
            "pi" => vec![(
                self.home
                    .join(".pi")
                    .join("agent")
                    .join("extensions")
                    .join("ageminal.ts"),
                pi_extension(&self.shim_target()),
            )],
            _ => Vec::new(),
        }
    }

    fn plan(&self, agent: &str) -> Vec<PlannedFile> {
        if agent == "codex" {
            let path = self.codex_path();
            let old = fs::read_to_string(&path).ok();
            let content = codex_config(old.as_deref(), &self.shim_target());
            return vec![PlannedFile { path, content, old }];
        }
        self.files(agent)
            .into_iter()
            .map(|(path, content)| {
                let old = fs::read_to_string(&path).ok();
                PlannedFile { path, content, old }
            })
            .collect()
    }

    fn view(&self, agent: &str) -> IntegrationView {
        let supported = SUPPORTED.contains(&agent);
        let name = display_name(agent);
        if !supported {
            return IntegrationView {
                agent_id: agent.to_owned(),
                name,
                status: IntegrationStatus::Unsupported,
                applied: 0,
                total: 0,
                shim_ready: self.shim_target().is_file(),
                files: Vec::new(),
                last_delivery_ms: last_success_ms(&self.local),
                failure_count: failure_count(&self.local),
                detail: Some("该 agent 暂不支持集成".to_owned()),
            };
        }

        if agent == "codex" {
            let path = self.codex_path();
            let old = fs::read_to_string(&path).ok();
            let expected = codex_config(old.as_deref(), &self.shim_target());
            let has_notify = old.as_deref().is_some_and(has_notify);
            let matches = old.as_deref() == Some(expected.as_str());
            let status = if matches {
                IntegrationStatus::Enabled
            } else if has_notify {
                IntegrationStatus::UpdateAvailable
            } else {
                IntegrationStatus::NotEnabled
            };
            return IntegrationView {
                agent_id: agent.to_owned(),
                name,
                status,
                applied: u32::from(matches),
                total: 1,
                shim_ready: self.shim_target().is_file(),
                files: vec![IntegrationFileView {
                    path: path_text(&path),
                    action: if matches {
                        IntegrationAction::Unchanged
                    } else if old.is_some() {
                        IntegrationAction::Update
                    } else {
                        IntegrationAction::Create
                    },
                }],
                last_delivery_ms: last_success_ms(&self.local),
                failure_count: failure_count(&self.local),
                detail: None,
            };
        }

        let plans = self.plan(agent);
        let total = plans.len() as u32;
        let mut matched = 0u32;
        let mut existing = 0u32;
        let mut ours_existing = 0u32;
        let claude_root = self.home.join(".claude").join("skills").join("ageminal");
        let mut files = Vec::with_capacity(plans.len());
        for plan in &plans {
            let old_is_ours = plan.old.as_deref().is_some_and(|old| {
                old.contains(GENERATED_MARKER) || plan.path.starts_with(&claude_root)
            });
            if plan.old.is_some() && old_is_ours {
                ours_existing += 1;
            }
            let action = match plan.old.as_deref() {
                None => IntegrationAction::Create,
                Some(old) if old == plan.content => {
                    matched += 1;
                    existing += 1;
                    IntegrationAction::Unchanged
                }
                Some(_) => {
                    existing += 1;
                    IntegrationAction::Update
                }
            };
            files.push(IntegrationFileView {
                path: path_text(&plan.path),
                action,
            });
        }
        let status = if matched == total {
            IntegrationStatus::Enabled
        } else if existing == total && ours_existing > 0 {
            IntegrationStatus::UpdateAvailable
        } else if ours_existing > 0 {
            IntegrationStatus::Partial
        } else {
            // 目标路径上有用户的同名文件，但没有任何 Ageminal 标记：尚未安装，不能声称
            // 「集成有更新」。预览仍会把它当作 update + backup 处理。
            IntegrationStatus::NotEnabled
        };
        IntegrationView {
            agent_id: agent.to_owned(),
            name,
            status,
            applied: matched,
            total,
            shim_ready: self.shim_target().is_file(),
            files,
            last_delivery_ms: last_success_ms(&self.local),
            failure_count: failure_count(&self.local),
            detail: None,
        }
    }

    fn preview(&self, agent: &str) -> IntegrationPreview {
        let supported = SUPPORTED.contains(&agent);
        let name = display_name(agent);
        if !supported {
            return IntegrationPreview {
                agent_id: agent.to_owned(),
                name,
                supported: false,
                shim_ready: self.shim_target().is_file(),
                files: Vec::new(),
            };
        }
        let files = self
            .plan(agent)
            .into_iter()
            .map(|plan| {
                let action = match plan.old.as_deref() {
                    None => IntegrationAction::Create,
                    Some(old) if old == plan.content => IntegrationAction::Unchanged,
                    Some(_) => IntegrationAction::Update,
                };
                let backup = (action == IntegrationAction::Update
                    && plan.old.as_deref().is_some_and(|old| !is_generated(old)))
                .then(|| path_text(&backup_path(&plan.path, crate::now_ms())));
                IntegrationPreviewFile {
                    path: path_text(&plan.path),
                    action,
                    diff: diff(&path_text(&plan.path), plan.old.as_deref(), &plan.content),
                    backup,
                }
            })
            .collect();
        IntegrationPreview {
            agent_id: agent.to_owned(),
            name,
            supported,
            shim_ready: self.shim_target().is_file(),
            files,
        }
    }

    fn apply(&self, agent: &str) -> Result<IntegrationApplyResult, String> {
        if !SUPPORTED.contains(&agent) {
            return Err(format!("{agent} 不支持 Ageminal 集成"));
        }
        self.ensure_shim()?;
        let stamp = crate::now_ms();
        let mut backups = Vec::new();
        let mut errors = Vec::new();
        let mut restart_required = false;
        for plan in self.plan(agent) {
            if plan.old.as_deref() == Some(plan.content.as_str()) {
                continue;
            }
            if plan.old.as_deref().is_some_and(|old| !is_generated(old)) {
                let backup = backup_path(&plan.path, stamp);
                if let Err(error) = fs::copy(&plan.path, &backup) {
                    errors.push(format!("备份 {} 失败：{error}", path_text(&plan.path)));
                    continue;
                }
                backups.push(path_text(&backup));
            }
            if let Some(parent) = plan.path.parent() {
                if let Err(error) = fs::create_dir_all(parent) {
                    errors.push(format!("创建 {} 失败：{error}", path_text(parent)));
                    continue;
                }
            }
            match fs::write(&plan.path, &plan.content) {
                Ok(()) => restart_required = true,
                Err(error) => errors.push(format!("写入 {} 失败：{error}", path_text(&plan.path))),
            }
        }
        Ok(IntegrationApplyResult {
            view: self.view(agent),
            backups,
            errors,
            restart_required,
        })
    }

    fn disable(&self, agent: &str) -> Result<IntegrationApplyResult, String> {
        if !SUPPORTED.contains(&agent) {
            return Err(format!("{agent} 不支持 Ageminal 集成"));
        }
        let mut errors = Vec::new();
        let mut restart_required = false;
        if agent == "codex" {
            let path = self.codex_path();
            if let Ok(old) = fs::read_to_string(&path) {
                if has_notify(&old) {
                    let updated = codex_remove(&old);
                    if updated.trim().is_empty() {
                        if let Err(error) = fs::remove_file(&path) {
                            errors.push(format!("删除 {} 失败：{error}", path_text(&path)));
                        } else {
                            restart_required = true;
                        }
                    } else if let Err(error) = fs::write(&path, updated) {
                        errors.push(format!("写入 {} 失败：{error}", path_text(&path)));
                    } else {
                        restart_required = true;
                    }
                }
            }
        } else if agent == "claude" {
            let root = self.home.join(".claude").join("skills").join("ageminal");
            if root.exists() {
                if let Err(error) = fs::remove_dir_all(&root) {
                    errors.push(format!("删除 {} 失败：{error}", path_text(&root)));
                } else {
                    restart_required = true;
                }
            }
        } else {
            for (path, _) in self.files(agent) {
                if !path.exists() {
                    continue;
                }
                // 如果这是我们覆盖用户文件前留下的备份，停用应恢复用户原文；否则删除我们自己
                // 投放的文件。备份也带 Ageminal 标记时说明它只是旧版本。
                let restore = latest_backup(&path)
                    .and_then(|backup| fs::read_to_string(&backup).ok())
                    .filter(|content| !is_generated(content));
                if let Some(content) = restore {
                    if let Err(error) = fs::write(&path, content) {
                        errors.push(format!("恢复 {} 失败：{error}", path_text(&path)));
                    } else {
                        restart_required = true;
                    }
                } else if let Err(error) = fs::remove_file(&path) {
                    errors.push(format!("删除 {} 失败：{error}", path_text(&path)));
                } else {
                    restart_required = true;
                }
                // 只删除我们创建后变空的 plugins / extensions 目录；不碰用户已有目录。
                if !path.exists() {
                    if let Some(parent) = path.parent() {
                        let _ = fs::remove_dir(parent);
                    }
                }
            }
        }
        Ok(IntegrationApplyResult {
            view: self.view(agent),
            backups: Vec::new(),
            errors,
            restart_required,
        })
    }

    fn test_delivery(&self, agent: &str) -> Result<IntegrationTestResult, String> {
        if !SUPPORTED.contains(&agent) {
            return Err(format!("{agent} 不支持 Ageminal 集成"));
        }
        let shim = self.ensure_shim()?;
        let info = DaemonInfo::read(&self.config_dir())
            .map_err(|error| format!("读取 daemon.json 失败：{error}"))?;
        let sid = format!("integration-test-{}", crate::now_ms());
        let output = Command::new(&shim)
            .arg("--agent")
            .arg(agent)
            .arg("--event")
            .arg("integration-test")
            .arg("--json")
            .arg(r#"{"probe":true}"#)
            .arg("--strict")
            .env("AGEMINAL_SESSION_ID", &sid)
            .env("AGEMINAL_INCARNATION", "integration-test")
            .env("AGEMINAL_PIPE", &info.pipe)
            .env("AGEMINAL_TOKEN", &info.token)
            .env(
                "AGEMINAL_WORKTREE",
                std::env::current_dir()
                    .map(|path| path_text(&path))
                    .unwrap_or_default(),
            )
            .env("AGEMINAL_AGENT", agent)
            .stdin(Stdio::null())
            .output()
            .map_err(|error| format!("启动 ageminal-notify 失败：{error}"))?;
        let delivered = output.status.success();
        let detail = if delivered {
            "shim 已完成握手并投递到 daemon".to_owned()
        } else {
            let stderr = String::from_utf8_lossy(&output.stderr);
            let stdout = String::from_utf8_lossy(&output.stdout);
            format!(
                "shim 退出码 {:?}：{}{}",
                output.status.code(),
                stdout.trim(),
                stderr.trim()
            )
        };
        Ok(IntegrationTestResult {
            delivered,
            detail,
            last_delivery_ms: last_success_ms(&self.local),
            failure_count: failure_count(&self.local),
        })
    }
}

fn find_shim(exe: &Path) -> Result<PathBuf, String> {
    let Some(parent) = exe.parent() else {
        return Err("无法定位应用目录".to_owned());
    };
    let exact = parent.join("ageminal-notify.exe");
    if exact.is_file() {
        return Ok(exact);
    }
    let entries = fs::read_dir(parent).map_err(|error| error.to_string())?;
    for entry in entries.flatten() {
        let name = entry.file_name();
        let name = name.to_string_lossy();
        if name.starts_with("ageminal-notify") && name.ends_with(".exe") {
            return Ok(entry.path());
        }
    }
    Ok(exact)
}

fn display_name(agent: &str) -> String {
    AGENT_DEFAULTS
        .iter()
        .find(|default| default.id == agent)
        .map(|default| default.name.to_owned())
        .unwrap_or_else(|| agent.to_owned())
}

fn claude_plugin_json() -> String {
    serde_json::to_string_pretty(&json!({
        "name": "ageminal",
        "description": format!("{GENERATED_MARKER}: agent status hooks for Ageminal"),
        "version": format!("{INTEGRATION_VERSION}.0.0"),
        "author": { "name": "Ageminal" }
    }))
    .expect("plugin json")
}

fn claude_hooks_json(shim: &Path) -> String {
    let events = [
        "SessionStart",
        "UserPromptSubmit",
        "PreToolUse",
        "PostToolUse",
        "PostToolUseFailure",
        "PermissionRequest",
        "PermissionDenied",
        "Notification",
        "Stop",
        "StopFailure",
        "SessionEnd",
    ];
    let mut hooks = serde_json::Map::new();
    for event in events {
        hooks.insert(
            event.to_owned(),
            json!([{
                "hooks": [{
                    "type": "command",
                    "command": format!("\"{}\" --agent claude --event {event}", shim.display()),
                    "async": true
                }]
            }]),
        );
    }
    serde_json::to_string_pretty(&json!({ "hooks": hooks })).expect("hooks json")
}

fn js_string(value: &str) -> String {
    serde_json::to_string(value).expect("js string")
}

fn opencode_plugin(shim: &Path) -> String {
    let shim = js_string(&path_text(shim));
    format!(
        r#"// {GENERATED_MARKER} (integration v{INTEGRATION_VERSION}). Do not edit.
import {{ spawn }} from "node:child_process";

const SHIM = {shim};
const AGENT = "opencode";
const EXTRA_ACTIVITY = /^(message|file|todo)\./;

function shouldSend(type: string): boolean {{
  return (
    type === "session.created" ||
    type === "session.updated" ||
    type === "session.status" ||
    type === "session.idle" ||
    type === "session.error" ||
    type === "session.compacted" ||
    type === "permission.asked" ||
    type === "permission.replied" ||
    type === "question.asked" ||
    type === "question.replied" ||
    type === "question.rejected" ||
    EXTRA_ACTIVITY.test(type)
  );
}}

function emit(type: string, payload: unknown): void {{
  try {{
    const child = spawn(
      SHIM,
      ["--agent", AGENT, "--event", type, "--json", JSON.stringify(payload ?? {{}})],
      {{ detached: true, stdio: "ignore", windowsHide: true, env: process.env }},
    );
    child.unref();
  }} catch {{
    // 状态回调是旁路：永远不能影响 opencode 本身。
  }}
}}

export const AgeminalPlugin = async () => ({{
  event: async ({{ event }}: {{ event?: {{ type?: string }} }}) => {{
    const type = event?.type;
    if (typeof type !== "string" || !shouldSend(type)) return;
    emit(type, event);
  }},
}});
"#
    )
}

fn pi_extension(shim: &Path) -> String {
    let shim = js_string(&path_text(shim));
    format!(
        r#"// {GENERATED_MARKER} (integration v{INTEGRATION_VERSION}). Do not edit.
const SHIM = {shim};
const AGENT = "pi";
const EVENTS = [
  "session_start",
  "agent_start",
  "turn_start",
  "agent_end",
  "agent_settled",
  "auto_retry_start",
  "auto_retry_end",
  "session_compact_failed",
  "extension_error",
  "ui_prompt_start",
  "ui_prompt_end",
  "tool_execution_start",
  "tool_execution_end",
  "tool_call",
  "queue_update",
  "session_shutdown",
];

function emit(type, payload) {{
  try {{
    const {{ spawn }} = require("node:child_process");
    const child = spawn(
      SHIM,
      ["--agent", AGENT, "--event", type, "--json", JSON.stringify(payload ?? {{}})],
      {{ detached: true, stdio: "ignore", windowsHide: true, env: process.env }},
    );
    child.unref();
  }} catch {{
    // 状态回调是旁路：永远不能影响 pi 本身。
  }}
}}

export default function ageminal(pi) {{
  for (const name of EVENTS) {{
    pi.on(name, async (event) => {{
      emit(name, event);
    }});
  }}
}}
"#
    )
}

fn codex_config(old: Option<&str>, shim: &Path) -> String {
    let old = old.unwrap_or("");
    let newline = if old.contains("\r\n") { "\r\n" } else { "\n" };
    let line = codex_notify_line(shim);
    if let Some(span) = find_notify_span(old) {
        let mut out = String::with_capacity(old.len() + line.len());
        out.push_str(&old[..span.start]);
        out.push_str(&line);
        out.push_str(&old[span.value_end..]);
        out
    } else if old.is_empty() {
        format!("{line}{newline}")
    } else {
        format!("{line}{newline}{old}")
    }
}

fn codex_remove(old: &str) -> String {
    let Some(span) = find_notify_span(old) else {
        return old.to_owned();
    };
    let mut out = String::with_capacity(old.len());
    out.push_str(&old[..span.start]);
    out.push_str(&old[span.line_end..]);
    out
}

fn codex_notify_line(shim: &Path) -> String {
    format!(
        "notify = [{}, \"--agent\", \"codex\", \"--event\", \"agent-turn-complete\"]",
        js_string(&path_text(shim))
    )
}

fn has_notify(text: &str) -> bool {
    find_notify_span(text).is_some()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct NotifySpan {
    /// `notify` 所在行首的字节偏移。
    start: usize,
    /// 数组右括号之后的字节偏移。
    value_end: usize,
    /// 所在行（含换行）的结束偏移。
    line_end: usize,
}

/// 找**顶层** `notify = [...]` 的文本范围；只扫描第一个 `[table]` 之前。
fn find_notify_span(text: &str) -> Option<NotifySpan> {
    let mut offset = 0usize;
    for line in text.split_inclusive('\n') {
        let trimmed = line.trim_start();
        if trimmed.starts_with('[') {
            break;
        }
        let leading = line.len() - trimmed.len();
        if let Some(rest) = trimmed.strip_prefix("notify") {
            let rest_trimmed = rest.trim_start();
            if let Some(after_eq) = rest_trimmed.strip_prefix('=') {
                let value_start = offset
                    + leading
                    + (line.len() - leading - rest.len())
                    + (rest.len() - rest_trimmed.len())
                    + 1
                    + (after_eq.len() - after_eq.trim_start().len());
                if text.as_bytes().get(value_start) == Some(&b'[') {
                    let mut depth = 0i32;
                    let mut quote: Option<u8> = None;
                    let mut escaped = false;
                    let mut comment = false;
                    let mut value_end = None;
                    for (index, byte) in text.as_bytes().iter().enumerate().skip(value_start) {
                        if comment {
                            if *byte == b'\n' {
                                comment = false;
                            }
                            continue;
                        }
                        if let Some(current) = quote {
                            if escaped {
                                escaped = false;
                            } else if *byte == b'\\' {
                                escaped = true;
                            } else if *byte == current {
                                quote = None;
                            }
                            continue;
                        }
                        match *byte {
                            b'#' => comment = true,
                            b'"' | b'\'' => quote = Some(*byte),
                            b'[' => depth += 1,
                            b']' => {
                                depth -= 1;
                                if depth == 0 {
                                    value_end = Some(index + 1);
                                    break;
                                }
                            }
                            _ => {}
                        }
                    }
                    let value_end = value_end?;
                    let line_end = text[value_end..]
                        .find('\n')
                        .map(|relative| value_end + relative + 1)
                        .unwrap_or(text.len());
                    return Some(NotifySpan {
                        start: offset,
                        value_end,
                        line_end,
                    });
                }
            }
        }
        offset += line.len();
    }
    None
}

fn diff(path: &str, old: Option<&str>, new: &str) -> String {
    let old = old.unwrap_or("");
    if old == new {
        return String::new();
    }
    let mut out = format!("--- {path}\n+++ {path}\n");
    for line in old.lines() {
        out.push('-');
        out.push_str(line);
        out.push('\n');
    }
    for line in new.lines() {
        out.push('+');
        out.push_str(line);
        out.push('\n');
    }
    out
}

fn backup_path(path: &Path, stamp: u64) -> PathBuf {
    PathBuf::from(format!("{}.ageminal-backup-{stamp}", path_text(path)))
}

fn latest_backup(path: &Path) -> Option<PathBuf> {
    let parent = path.parent()?;
    let prefix = format!("{}.ageminal-backup-", path.file_name()?.to_string_lossy());
    let mut backups: Vec<PathBuf> = fs::read_dir(parent)
        .ok()?
        .flatten()
        .map(|entry| entry.path())
        .filter(|candidate| {
            candidate
                .file_name()
                .is_some_and(|name| name.to_string_lossy().starts_with(&prefix))
        })
        .collect();
    backups.sort();
    backups.pop()
}

fn is_generated(content: &str) -> bool {
    content.contains(GENERATED_MARKER)
}

fn path_text(path: &Path) -> String {
    path.to_string_lossy()
        .replace('/', std::path::MAIN_SEPARATOR_STR)
}

fn last_success_ms(local: &Path) -> Option<f64> {
    let path = local
        .join("Ageminal")
        .join("logs")
        .join("notify-success.log");
    let contents = fs::read_to_string(path).ok()?;
    contents
        .lines()
        .rev()
        .find_map(|line| line.split_whitespace().next()?.parse::<u64>().ok())
        .map(|value| value as f64)
}

fn failure_count(local: &Path) -> u32 {
    let path = local
        .join("Ageminal")
        .join("logs")
        .join("notify-failures.log");
    fs::read_to_string(path)
        .map(|contents| {
            contents
                .lines()
                .filter(|line| !line.trim().is_empty())
                .count()
                .min(u32::MAX as usize) as u32
        })
        .unwrap_or(0)
}

/// 卸载钩子：只清理仍带 Ageminal 标记的集成；用户改过的文件保持不动。
///
/// 不删除 `%LOCALAPPDATA%\Ageminal` 用户数据；只清理 agent 全局注入物。
pub fn uninstall_cleanup() {
    let Ok(context) = IntegrationContext::load() else {
        return;
    };
    cleanup_marked(&context);
}

fn cleanup_marked(context: &IntegrationContext) {
    let claude_root = context.home.join(".claude").join("skills").join("ageminal");
    let manifest = claude_root.join(".claude-plugin").join("plugin.json");
    if fs::read_to_string(&manifest)
        .map(|content| content.contains(GENERATED_MARKER))
        .unwrap_or(false)
    {
        let _ = fs::remove_dir_all(&claude_root);
    }

    for (path, _) in context
        .files("opencode")
        .into_iter()
        .chain(context.files("pi"))
    {
        if fs::read_to_string(&path)
            .map(|content| content.contains(GENERATED_MARKER))
            .unwrap_or(false)
        {
            let _ = fs::remove_file(&path);
            if let Some(parent) = path.parent() {
                let _ = fs::remove_dir(parent);
            }
        }
    }

    let codex = context.codex_path();
    if let Ok(old) = fs::read_to_string(&codex) {
        if let Some(span) = find_notify_span(&old) {
            let block = &old[span.start..span.value_end];
            if block.contains("ageminal-notify") {
                let updated = codex_remove(&old);
                if updated.trim().is_empty() {
                    let _ = fs::remove_file(&codex);
                } else {
                    let _ = fs::write(&codex, updated);
                }
            }
        }
    }
}

/// 应用启动时把 sidecar 复制到稳定路径；失败只记录，不影响启动。
pub fn ensure_shim() {
    match IntegrationContext::load().and_then(|context| context.ensure_shim()) {
        Ok(path) => tracing::warn!("[integration] shim ready: {}", path.display()),
        Err(error) => tracing::warn!("[integration] shim 不可用：{error}"),
    }
}

fn context() -> Result<IntegrationContext, String> {
    IntegrationContext::load()
}

/// 列出四个 agent 的集成状态（Codex 显示 unsupported）。
#[tauri::command]
#[specta::specta]
pub fn integration_list() -> Result<Vec<IntegrationView>, String> {
    let context = context()?;
    Ok(AGENT_DEFAULTS
        .iter()
        .map(|agent| context.view(agent.id))
        .collect())
}

/// 应用前 diff 预览。
#[tauri::command]
#[specta::specta]
pub fn integration_preview(agent_id: String) -> Result<IntegrationPreview, String> {
    let context = context()?;
    Ok(context.preview(&agent_id))
}

/// 确认应用投放。
#[tauri::command]
#[specta::specta]
pub fn integration_apply(agent_id: String) -> Result<IntegrationApplyResult, String> {
    let context = context()?;
    context.apply(&agent_id)
}

/// 停用并回滚。
#[tauri::command]
#[specta::specta]
pub fn integration_disable(agent_id: String) -> Result<IntegrationApplyResult, String> {
    let context = context()?;
    context.disable(&agent_id)
}

/// 测试投递：跑一次真实 shim，验证 pipe / token / daemon 链路。
