pub fn integration_test_delivery(agent_id: String) -> Result<IntegrationTestResult, String> {
    let context = context()?;
    context.test_delivery(&agent_id)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::{AtomicU32, Ordering};

    static COUNTER: AtomicU32 = AtomicU32::new(0);

    fn fixture() -> (IntegrationContext, PathBuf) {
        let root = std::env::temp_dir().join(format!(
            "ageminal-integration-{}-{}",
            std::process::id(),
            COUNTER.fetch_add(1, Ordering::Relaxed)
        ));
        let _ = fs::remove_dir_all(&root);
        let home = root.join("home");
        let local = root.join("local");
        fs::create_dir_all(&home).unwrap();
        fs::create_dir_all(&local).unwrap();
        let shim = root.join("ageminal-notify.exe");
        fs::write(&shim, b"notify").unwrap();
        (
            IntegrationContext {
                home,
                local,
                shim_source: shim,
            },
            root,
        )
    }

    #[test]
    fn three_agents_have_idempotent_file_sets() {
        for (agent, expected) in [("claude", 2usize), ("opencode", 1), ("pi", 1)] {
            let (context, root) = fixture();
            let preview = context.preview(agent);
            assert!(preview.supported);
            assert_eq!(preview.files.len(), expected);
            assert!(preview
                .files
                .iter()
                .all(|file| file.action == IntegrationAction::Create));
            assert!(preview
                .files
                .iter()
                .any(|file| file.diff.starts_with("--- ")));
            assert!(context.view(agent).status == IntegrationStatus::NotEnabled);

            let first = context.apply(agent).unwrap();
            assert!(first.errors.is_empty(), "{:?}", first.errors);
            assert!(first.view.status == IntegrationStatus::Enabled);
            assert!(first.backups.is_empty());
            assert!(context.shim_target().is_file());

            let second = context.apply(agent).unwrap();
            assert!(second.errors.is_empty());
            assert!(second.backups.is_empty());
            assert!(!second.restart_required);
            assert!(second.view.status == IntegrationStatus::Enabled);

            let disabled = context.disable(agent).unwrap();
            assert!(disabled.errors.is_empty());
            assert!(context.view(agent).status == IntegrationStatus::NotEnabled);
            let _ = fs::remove_dir_all(root);
        }
    }

    #[test]
    fn existing_user_file_is_backed_up_and_restored_on_disable() {
        let (context, root) = fixture();
        let target = context
            .home
            .join(".config")
            .join("opencode")
            .join("plugins")
            .join("ageminal.ts");
        fs::create_dir_all(target.parent().unwrap()).unwrap();
        fs::write(&target, "// user file\n").unwrap();

        let applied = context.apply("opencode").unwrap();
        assert_eq!(applied.backups.len(), 1);
        let backup = PathBuf::from(&applied.backups[0]);
        assert!(backup.is_file());
        assert_eq!(
            fs::read_to_string(&target).unwrap(),
            opencode_plugin(&context.shim_target())
        );

        let disabled = context.disable("opencode").unwrap();
        assert!(disabled.errors.is_empty());
        assert_eq!(fs::read_to_string(&target).unwrap(), "// user file\n");
        assert_eq!(
            context.view("opencode").status,
            IntegrationStatus::NotEnabled,
            "恢复用户文件后不能声称集成仍启用"
        );
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn content_change_is_reported_as_update_available() {
        let (context, root) = fixture();
        context.apply("pi").unwrap();
        let file = context.files("pi").remove(0).0;
        fs::write(&file, format!("// {GENERATED_MARKER} stale\n")).unwrap();

        let view = context.view("pi");
        assert_eq!(view.status, IntegrationStatus::UpdateAvailable);
        assert_eq!(view.applied, 0);
        assert_eq!(view.total, 1);

        let applied = context.apply("pi").unwrap();
        assert!(applied.view.status == IntegrationStatus::Enabled);
        assert!(applied.backups.is_empty(), "我们自己的旧版本不需要备份");
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn diagnostics_read_last_success_and_failure_count() {
        let (context, root) = fixture();
        let logs = context.local.join("Ageminal").join("logs");
        fs::create_dir_all(&logs).unwrap();
        fs::write(
            logs.join("notify-success.log"),
            "1000 notify: delivered\n2000 notify: delivered\n",
        )
        .unwrap();
        fs::write(
            logs.join("notify-failures.log"),
            "1 notify: missing\n\n2 notify: refused\n",
        )
        .unwrap();
        assert_eq!(last_success_ms(&context.local), Some(2000.0));
        assert_eq!(failure_count(&context.local), 2);
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn codex_toml_is_textual_idempotent_and_reversible() {
        let (context, root) = fixture();
        let path = context.codex_path();
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        let original = "# keep this comment\nmodel = \"gpt-5\"\n\n[hooks]\nother = 1\n";
        fs::write(&path, original).unwrap();

        let first = context.apply("codex").unwrap();
        assert!(first.errors.is_empty());
        assert_eq!(first.view.status, IntegrationStatus::Enabled);
        assert_eq!(first.backups.len(), 1);
        let text = fs::read_to_string(&path).unwrap();
        assert!(text.contains(original));
        assert!(text.contains("notify = ["));
        assert!(text.contains("ageminal-notify.exe"));
        assert!(text.contains("agent-turn-complete"));

        let second = context.apply("codex").unwrap();
        assert!(second.backups.is_empty());
        assert_eq!(second.view.status, IntegrationStatus::Enabled);

        // 手工改成旧值 → 状态必须是 updateAvailable，而不是静默当已启用。
        fs::write(
            &path,
            "# keep this comment\nnotify = [\"old\"]\nmodel = \"gpt-5\"\n",
        )
        .unwrap();
        assert_eq!(
            context.view("codex").status,
            IntegrationStatus::UpdateAvailable
        );

        let disabled = context.disable("codex").unwrap();
        assert!(disabled.errors.is_empty());
        assert!(!has_notify(&fs::read_to_string(&path).unwrap()));
        assert!(
            !context.codex_path().exists()
                || context.view("codex").status == IntegrationStatus::NotEnabled
        );
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn codex_disable_restores_original_text_exactly() {
        let (context, root) = fixture();
        let path = context.codex_path();
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        let original = "# top\nmodel = \"gpt-5\"\n\n# before table\n[hooks]\nother = 1\n";
        fs::write(&path, original).unwrap();
        context.apply("codex").unwrap();
        context.disable("codex").unwrap();
        assert_eq!(fs::read_to_string(&path).unwrap(), original);
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn codex_file_created_from_nothing_is_removed_on_disable() {
        let (context, root) = fixture();
        context.apply("codex").unwrap();
        assert!(context.codex_path().is_file());
        context.disable("codex").unwrap();
        assert!(!context.codex_path().exists());
        assert_eq!(context.view("codex").status, IntegrationStatus::NotEnabled);
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn uninstall_cleanup_only_removes_marked_integrations() {
        let (context, root) = fixture();
        context.apply("claude").unwrap();
        context.apply("opencode").unwrap();
        let pi = context.files("pi").remove(0).0;
        fs::create_dir_all(pi.parent().unwrap()).unwrap();
        fs::write(&pi, "// user-owned extension\n").unwrap();
        let codex = context.codex_path();
        fs::create_dir_all(codex.parent().unwrap()).unwrap();
        fs::write(&codex, "# keep\nmodel = \"gpt-5\"\n").unwrap();
        context.apply("codex").unwrap();

        cleanup_marked(&context);

        let claude = context.home.join(".claude").join("skills").join("ageminal");
        assert!(!claude.exists(), "带标记的 Claude 插件目录应清理");
        assert!(
            !context.files("opencode")[0].0.exists(),
            "带标记的 opencode 文件应清理"
        );
        assert_eq!(
            fs::read_to_string(&pi).unwrap(),
            "// user-owned extension\n",
            "用户改过的 pi 文件不能删"
        );
        let codex_text = fs::read_to_string(&codex).unwrap();
        assert!(!codex_text.contains("notify"));
        assert!(codex_text.contains("model = \"gpt-5\""));
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn claude_plugin_renders_hooks_with_absolute_shim() {
        let (context, root) = fixture();
        let files = context.files("claude");
        assert_eq!(files.len(), 2);
        let hooks = &files[1].1;
        assert!(hooks.contains("SessionStart"));
        assert!(hooks.contains("PermissionRequest"));
        assert!(hooks.contains("ageminal-notify.exe"));
        assert!(!hooks.contains("PATH"));
        let plugin = &files[0].1;
        assert!(plugin.contains(GENERATED_MARKER));
        let _ = fs::remove_dir_all(root);
    }
}
